package com.motonav.protocol

import org.junit.jupiter.api.Assertions.assertArrayEquals
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

/** The simulated messages, against protocol/scenarios.txt (generated by the Python tool). */
class ScenariosTest {
    private val file = SharedFiles.scenarios()

    @Test
    fun theSharedFileHasTwelveValidMessagesAndFiveWrongOnes() {
        assertEquals(17, file.size)
        assertEquals(List(12) { false } + List(5) { true }, file.map { it.first.startsWith("BAD_") })
    }

    @Test
    fun theValidMessagesAreIdenticalToThePythonToolsByteForByte() {
        val mine = Scenarios.validFrames(startSeq = 1)
        assertEquals(file.take(12).map { it.first }, mine.map { it.first })
        for ((expected, actual) in file.take(12).zip(mine)) {
            assertArrayEquals(expected.second, actual.second, expected.first)
        }
    }

    @Test
    fun theWrongMessagesAreIdenticalToThePythonToolsByteForByte() {
        val mine = Scenarios.invalid(startSeq = 1)
        assertEquals(file.drop(12).map { it.first }, mine.map { it.name })
        for ((expected, actual) in file.drop(12).zip(mine)) {
            assertArrayEquals(expected.second, actual.frame, expected.first)
        }
    }

    @Test
    fun everyValidMessageDecodesToTheStateItWasMadeFrom() {
        for ((index, scenario) in Scenarios.valid.withIndex()) {
            val frame = FrameCodec.encode(scenario.update, index + 1)
            val decoded = FrameCodec.decode(frame) as DecodeResult.Ok
            assertEquals(index + 1, decoded.sequence, scenario.name)
            assertEquals(scenario.update, decoded.update, scenario.name)
        }
    }

    @Test
    fun everyWrongMessageIsRejectedForTheReasonItsDescriptionGives() {
        for (raw in Scenarios.invalid()) {
            val rejected = FrameCodec.decode(raw.frame) as? DecodeResult.Rejected ?: error("${raw.name} was accepted")
            assertTrue(raw.description.contains(rejected.error.name), "${raw.name}: ${raw.description} vs ${rejected.error}")
        }
    }

    @Test
    fun sequenceNumbersWrapAroundWhenTheStartIsHigh() {
        val frames = Scenarios.validFrames(startSeq = 250)
        val sequences = frames.map { (FrameCodec.decode(it.second) as DecodeResult.Ok).sequence }
        assertEquals(listOf(250, 251, 252, 253, 254, 255, 0, 1, 2, 3, 4, 5), sequences)
    }
}
